"""cmd.sh generation for build / run / post jobs. Scripts run under bin/featx-exec on any
node, so they may only rely on bash, coreutils and /usr/bin/python3 (stdlib + yaml)."""

from __future__ import annotations

import json
import shlex
from pathlib import Path

from . import config

HEADER = """#!/usr/bin/env bash
# generated by featx — job {job} of task {task}
set -uo pipefail
"""

PATCH_PY = r'''
import json, os, sys
mode, spec, save = sys.argv[1], sys.argv[2], sys.argv[3]
patches = json.load(open(spec))
if mode == "apply":
    saved = {}
    for p in patches:
        path = p["file"]
        text = open(path).read()
        if path not in saved:
            saved[path] = text
        n = text.count(p["find"])
        if n != 1:
            print(f"featx: patch failed: {path}: 'find' text matched {n} times (must be exactly 1)", file=sys.stderr)
            for f, t in saved.items():
                open(f, "w").write(t)
            sys.exit(3)
        open(path, "w").write(text.replace(p["find"], p["replace"]))
        print(f"featx: patched {path}")
    json.dump(saved, open(save, "w"))
else:
    if os.path.exists(save):
        for f, t in json.load(open(save)).items():
            open(f, "w").write(t)
            print(f"featx: restored {f}")
'''


def _exports(env: dict) -> str:
    return "".join(f"export {k}={shlex.quote(str(v))}\n" for k, v in (env or {}).items())


def build_script(task_id: str, spec: dict) -> str:
    wd = spec["workdir"]
    out = [HEADER.format(job="build", task=task_id), _exports(spec.get("env") or {})]
    out.append(f"cd {shlex.quote(wd)} || {{ echo 'featx: artifact missing: workdir {wd} not found' >&2; exit 2; }}\n")
    out.append('echo "featx: build on $(hostname -s) in $PWD at $(date)"\n')
    patches = spec.get("patches") or []
    if patches:
        out.append(f"cat > \"$FX_DIR/patches.json\" <<'FXEOF'\n{json.dumps(patches)}\nFXEOF\n")
        out.append(f"cat > \"$FX_DIR/patch.py\" <<'FXEOF'\n{PATCH_PY}\nFXEOF\n")
        out.append('trap \'python3 "$FX_DIR/patch.py" restore "$FX_DIR/patches.json" "$FX_DIR/patch-saved.json"\' EXIT\n')
        out.append('python3 "$FX_DIR/patch.py" apply "$FX_DIR/patches.json" "$FX_DIR/patch-saved.json" || exit 3\n')
    timeout = f"timeout {float(spec.get('timeout_hours', 10))}h "
    if spec.get("type") == "verilator":
        v = spec.get("verilator") or {}
        if v.get("bin_dir"):
            out.append(f"export PATH={shlex.quote(str(v['bin_dir']))}:$PATH\n")
        ds = f"DRAMSIM3_HOME={shlex.quote(str(v.get('dramsim3_home')))}" if v.get("dramsim3_home") else ""
        out.append('echo "== make emu (verilator) $(date)"\n')
        out.append(f"{timeout}make emu -j{v.get('jobs', 64)} {ds} {v.get('make_args', '')}\n")
        out.append('rc=$?\necho "== make emu rc=$rc $(date)"\n[ $rc -eq 0 ] || exit $rc\n')
    elif spec.get("type") == "script":
        body = spec.get("script") or ""
        out.append(f"cat > \"$FX_DIR/build-body.sh\" <<'FXEOF'\n{body}\nFXEOF\n")
        out.append(f'{timeout}bash "$FX_DIR/build-body.sh"\nrc=$?\n')
        out.append('[ $rc -eq 0 ] || { echo "featx: build script rc=$rc"; exit $rc; }\n')
    else:
        g = spec.get("gsim") or {}
        gbin, ds, jobs = g.get("gsim_bin"), g.get("dramsim3_home"), g.get("jobs", 64)
        common = f"GSIM=1 GSIM_BIN={shlex.quote(str(gbin))} DRAMSIM3_HOME={shlex.quote(str(ds))}"
        reuse = g.get("reuse_build_from")
        if reuse:
            out.append(f"echo '== reuse build tree from {reuse} (relink only)'\n")
            out.append(f"[ -d build ] || cp -a {shlex.quote(str(reuse))} build || exit 1\n")
            out.append("rm -f build/emu build/gsim-compile/emu\n")
        else:
            out.append('echo "== step1 make gsim $(date)"\n')
            out.append(f"{timeout}make gsim -j{jobs} {common} {g.get('step1_args', '')}\n")
            out.append('step1_rc=$?\n')
            out.append('echo "== step1 rc=$step1_rc $(date)"\n')
            out.append("[ -d build/gsim-compile ] || { echo 'featx: artifact missing: build/gsim-compile (step1 failed)'; exit 1; }\n")
            out.append('if [ "$step1_rc" -ne 0 ]; then\n'
                       '  echo "featx: GSIM step1 did not produce a final emulator; continuing with step2 relink (step1 rc=$step1_rc)" >&2\n'
                       'fi\n')
        out.append('echo "== step2 difftest emu $(date)"\n')
        out.append(f"{timeout}make -C difftest emu -j{jobs} {common} DESIGN_DIR=\"$PWD\" {g.get('step2_args', '')}\n")
        out.append('rc=$?\necho "== step2 rc=$rc $(date)"\n[ $rc -eq 0 ] || exit $rc\n')
    arts = spec.get("artifact") or "build/emu"
    arts = arts if isinstance(arts, list) else [arts, "build/gsim-compile/emu"]
    out.append("art=\n")
    for a in arts:
        out.append(f"[ -z \"$art\" ] && [ -x {shlex.quote(a)} ] && art={shlex.quote(a)}\n")
    out.append('[ -n "$art" ] || { echo "featx: artifact missing: none of ' + " ".join(arts) + '"; exit 4; }\n')
    out.append('cp -f "$art" "$FX_JOB_DIR/emu.new" && mv -f "$FX_JOB_DIR/emu.new" "$FX_JOB_DIR/emu" || exit 5\n')
    out.append('echo "featx: artifact $art -> $FX_JOB_DIR/emu"\n')
    return "".join(out)


def run_point_script(task_id: str, spec: dict, point: dict, command: str, inputs: dict[str, str]) -> str:
    """inputs: label -> path that must exist (trace file, or checkpoint + diff reference)."""
    out = [HEADER.format(job=point["name"], task=task_id)]
    ds = spec.get("dramsim3_home")
    if ds:
        out.append(f"export LD_LIBRARY_PATH={shlex.quote(str(ds))}/build${{LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}}\n")
    out.append(_exports(spec.get("env") or {}))
    for label, path in inputs.items():
        out.append(f"[ -e {shlex.quote(path)} ] || {{ echo {shlex.quote(f'featx: {label} not found: {path}')} >&2; exit 2; }}\n")
    emu = spec.get("emu")
    out.append(f"emu={shlex.quote(str(emu))}\n")
    out.append('[ -x "$emu" ] || { echo "featx: emu not executable: $emu" >&2; exit 2; }\n')
    out.append('mkdir -p "$FX_TMP/dramsim3"\n')
    out.append('{ echo "host=$(hostname -s) emu=$emu"; env | grep -E "^(TRACERTL|FX_)" ; } > env.txt\n')
    timeout = float(spec.get("timeout_hours", 72))
    out.append(f"timeout {timeout}h {command}\n")
    out.append("rc=$?\n")
    if spec.get("completion_marker", True):
        out.append('if [ $rc -eq 0 ] && ! grep -aqE "EXCEEDING CYCLE/INSTR LIMIT|GOOD TRAP" simulator_out.txt; then\n'
                   '  if grep -aqE "ABORT at pc|TraceRTL Stuck|TraceRTL Error at inst" simulator_out.txt simulator_err.txt; then\n'
                   '    echo "featx: emu exited 0 after an abort marker" >&2; exit 86\n'
                   '  fi\n'
                   '  echo "EXCEEDING CYCLE/INSTR LIMIT (featx: emu exited 0)"\n'
                   'fi\n')
    out.append("exit $rc\n")
    return "".join(out)


def perf_trigger_wrapper(spec: dict) -> str:
    """emu wrapper for perf_trigger (it passes -i <checkpoint>); mirrors the campaign
    tracertl_emu_wrapper.sh."""
    ds = spec.get("dramsim3_home")
    return f"""#!/usr/bin/env bash
set -uo pipefail
real_emu={shlex.quote(str(spec['emu']))}
trace_file=
args=()
while (($#)); do
  case "$1" in
    -i|--image) trace_file=$2; shift 2 ;;
    --image=*) trace_file=${{1#*=}}; shift ;;
    *) args+=("$1"); shift ;;
  esac
done
[[ -n "$trace_file" ]] || {{ echo "featx wrapper: no -i/--image" >&2; exit 2; }}
if [[ ! -e "$trace_file" && "$trace_file" == *_memory_.zstd ]]; then
  trace_file=${{trace_file%_memory_.zstd}}_.trace.zstd
fi
[[ -e "$trace_file" ]] || {{ echo "featx: trace file not found: $trace_file" >&2; exit 2; }}
export LD_LIBRARY_PATH={shlex.quote(str(ds))}/build${{LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}}
{_exports(spec.get('env') or {})}dramsim_outdir=$(mktemp -d "${{TMPDIR:-/tmp}}/featx-dramsim3.XXXXXX") || exit 1
trap 'rm -rf -- "$dramsim_outdir"' EXIT
"$real_emu" "${{args[@]}}" --tracertl-file "$trace_file" --dramsim3-outdir "$dramsim_outdir" --force-dump-result {spec.get('args', '')}
status=$?
((status == 0)) && echo "EXCEEDING CYCLE/INSTR LIMIT (TraceRTL stream completed)"
exit "$status"
"""


def perf_trigger_script(task_id: str, spec: dict, runset_dir: Path, servers: str) -> str:
    pt = spec["perf_trigger"]
    out = [HEADER.format(job="perf_trigger", task=task_id)]
    out.append(f"python3 {shlex.quote(pt['main'])} --gcpt-path {shlex.quote(pt['gcpt_path'])} "
               f"--json-path {shlex.quote(str(pt['json_path']))} --result-path {shlex.quote(str(runset_dir / 'run'))} "
               f"--emu-path {shlex.quote(str(runset_dir / 'run' / 'emu-wrapper.sh'))} "
               f"-W {spec['W']} -I {spec['I']} -T {pt.get('threads', 1)} --server-list {shlex.quote(servers)} "
               f"--run --log-level INFO\n")
    return "".join(out)


def post_script(task_id: str, step: str, cmd: str, env: dict | None = None) -> str:
    out = [HEADER.format(job=step, task=task_id), _exports(env or {})]
    out.append(f"export FEATX_HOME={shlex.quote(str(config.REPO_DIR))}\n")
    out.append(cmd.rstrip() + "\n")
    return "".join(out)
